function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', C='#38bdf8', CL='#a8e8ff', CD='#2080c0';
  px(14,2,4,28,O);
  px(15,3,2,26,C);
  px(15,3,2,4,CL);
  px(13,6,6,2,O); px(14,7,4,1,CL);
  px(13,14,6,2,O); px(14,15,4,1,CL);
  px(12,22,8,2,O); px(13,23,6,1,CD);
}
